sys_script_client.script:
function onLoad() {
   var status = g_form.getValue('status');
   switch(status){
		case '1': //New
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','5');
			g_form.removeOption('status','6');
			g_form.removeOption('status','7');
			g_form.removeOption('status','8');
			g_form.removeOption('status','9');
			g_form.removeOption('status','10');
			g_form.removeOption('status','11');
			break;
		case '2': //Implementation documents
			g_form.removeOption('status','1');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','5');
			g_form.removeOption('status','6');
			g_form.removeOption('status','8');
			g_form.removeOption('status','10');
			g_form.removeOption('status','11');
			break;
		case '3': //Installed
			g_form.removeOption('status','1');
			g_form.removeOption('status','2');
			g_form.removeOption('status','5');
			g_form.removeOption('status','6');
			g_form.removeOption('status','7');
			g_form.removeOption('status','8');
			g_form.removeOption('status','9');
			g_form.removeOption('status','10');
			g_form.removeOption('status','11');
			break;
		case '5': //Closed
			g_form.removeOption('status','1');
			g_form.removeOption('status','2');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','6');
			g_form.removeOption('status','7');
			g_form.removeOption('status','9');
			g_form.removeOption('status','10');
			g_form.removeOption('status','11');
			break;
		case '6': //Terminated
			g_form.removeOption('status','1');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','5');
			g_form.removeOption('status','7');
			g_form.removeOption('status','8');
			g_form.removeOption('status','9');
			g_form.removeOption('status','10');
			break;
		case '8': //Validated
			g_form.removeOption('status','1');
			g_form.removeOption('status','2');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','5');
			g_form.removeOption('status','6');
			g_form.removeOption('status','9');
			g_form.removeOption('status','10');
			g_form.removeOption('status','11');
			break;
		case '9': //IDC reconciliation
			g_form.removeOption('status','1');
			g_form.removeOption('status','2');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','5');
			g_form.removeOption('status','6');
			g_form.removeOption('status','8');
			g_form.removeOption('status','11');
			break;
		case '10': //ADT reconciliation
			g_form.removeOption('status','1');
			g_form.removeOption('status','2');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','5');
			g_form.removeOption('status','6');
			g_form.removeOption('status','8');
			g_form.removeOption('status','9');
			break;
		case '11': //Invoiced
			g_form.removeOption('status','1');
			g_form.removeOption('status','3');
			g_form.removeOption('status','4');
			g_form.removeOption('status','6');
			g_form.removeOption('status','8');
			g_form.removeOption('status','9');
			g_form.removeOption('status','10');
			break;
   }
}
